describe("Cart — pricing pipeline", () => {
  it("applies discount → tax → shipping in correct order", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(720),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 5000), 2); // subtotal = 10000

    const t = cart.totals();

    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000);
    // Tax is computed on discounted subtotal (10000 - 1000 = 9000)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(9000, "US-CA");
    expect(t.taxCents).toBe(720);
    // Shipping receives discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      9000,
    );
    expect(t.shippingCents).toBe(500);
    // total = discounted subtotal + tax + shipping = 9000 + 720 + 500
    expect(t.totalCents).toBe(10220);
  });

  it("clamps discount to [0, subtotal]", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses defaults (no discount, no tax, free shipping) when no config", () => {
    const cart = new Cart();
    cart.add(product("a", 2500), 4);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(10000);
  });

  it("defaults region to US", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart — checkout()", () => {
  const p = product("widget", 1000);

  it("returns totals and lines for a simple checkout", async () => {
    const cart = new Cart();
    cart.add(p, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      } satisfies InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
      expect(ie.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available: true but qty insufficient)", async () => {
    const cart = new Cart();
    cart.add(product("b", 500), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("b");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 5000), 2); // subtotal = 10000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // discount = 500, discounted = 9500, tax = floor(9500 * 0.10) = 950
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(950);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(9500 + 950 + 300);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(400),
    };
    const cart = new Cart({ shippingCalculator: shipping, region: "DE" });
    cart.add(product("x", 1000), 3);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.19),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // refreshed: 2000 * 3 = 6000 subtotal, no discount → taxable = 6000
    // tax = floor(6000 * 0.19) = 1140
    expect(result.totals.subtotalCents).toBe(6000);
    expect(result.totals.taxCents).toBe(1140);
    expect(result.totals.shippingCents).toBe(400);
    expect(result.totals.totalCents).toBe(6000 + 1140 + 400);

    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("x");
    expect(inventoryChecker.check).toHaveBeenCalledWith("x", 3);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("DE");
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("first inventory denial wins for multiple lines", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 1);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({
          available: false,
          reason: "discontinued",
        }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("b");
      expect(ie.message).toBe("discontinued");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [10000, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "out-of-range"],
      [101, "out-of-range"],
      [NaN, "out-of-range"],
      [Infinity, "out-of-range"],
    ])("rejects percent=%s", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts percent=%i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 → 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent (10% of 999 → 99)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(999)).toBe(99);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(15_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when they match", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 1000
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("can exceed subtotal (clamping is done by Cart)", () => {
      const p1 = new PercentageDiscountPolicy(80); // 8000
      const p2 = new FixedAmountDiscountPolicy(5000); // 5000
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum mode: 8000 + 5000 = 13000 (exceeds 10000, but clamping is Cart's job)
      expect(composite.computeDiscountCents(10000)).toBe(13000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      // 10000 → 10% off = 1000 discount, remaining 9000 → fixed 200 off (capped at 9000)
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // p1 on 10000 → 1000; remaining 9000; p2 on 9000 → 200; total = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("chain ordering matters: different order yields different result", () => {
      // 50% then fixed 2000: 10000 → 5000 disc, remaining 5000 → 2000 disc → total 7000
      const pct = new PercentageDiscountPolicy(50);
      const fix = new FixedAmountDiscountPolicy(2000);
      const a = new CompositeDiscountPolicy([pct, fix], "chain");
      const b = new CompositeDiscountPolicy([fix, pct], "chain");
      // a: 50% of 10000=5000, remaining=5000; fixed=min(2000,5000)=2000; total=7000
      expect(a.computeDiscountCents(10000)).toBe(7000);
      // b: fixed=min(2000,10000)=2000, remaining=8000; 50% of 8000=4000; total=6000
      expect(b.computeDiscountCents(10000)).toBe(6000);
    });

    it("chain caps each step at remaining, never exceeding subtotal", () => {
      // Two fixed 6000 on subtotal 10000
      const p1 = new FixedAmountDiscountPolicy(6000);
      const p2 = new FixedAmountDiscountPolicy(6000);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // p1: min(6000, 10000)=6000, remaining=4000; p2: min(6000, 4000)=4000; total=10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

