    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("preserves other product fields", async () => {
